entire brain brief "Add a trail runner that builds the branch entire-brain binary, runs memories eval against a frozen labeled task set and a fixture brain store, compares to base branch, emits trail_monitor" --json 2>/dev/null | python3 -c "
import json,sys; d=json.load(sys.stdin)
for f in d.get('facts',[]): print('FACT',f['id'],f['paths'],f['text'][:300])
for h in d.get('history',{}).get('matches',[]): print('HIST',h['path'][-40:],h['line'],h['excerpt'][:200])
print('EDIT',d.get('likely_edit_files')); print('TEST',d.get('likely_test_files')); print('WARN',d.get('warnings'))"

