		func(ctx context.Context, in *RunnerSettingsInput) (*RunnerSettingsOutput, error) {
			if in.Body.RunnersEnabled == nil && in.Body.AutoRunOnPush == nil {
				return nil, huma.Error400BadRequest("At least one setting is required")
			}
			cur, err := deps.Store.GetRunnerSettings(ctx, in.RepoID)
			if err != nil {
