			}
			nextRunners := cur.RunnersEnabled
			if in.Body.RunnersEnabled != nil {
				nextRunners = *in.Body.RunnersEnabled
			}
			nextAuto := cur.AutoRunOnPush
			if auto != nil {
				nextAuto = *auto
			}
